interface.signature:
@DeleteMapping("/{customerId}")
@PreAuthorize("hasAnyRole('COMPLIANCE_OFFICER', 'ADMIN')")
public ResponseEntity<Void> deleteCustomer(
  @PathVariable UUID customerId,
  @RequestBody(required = false) DeleteCustomerRequest request
) {
  customerService.deleteCustomer(customerId, request != null ? request.getReason() : null);
  return ResponseEntity.ok().build(); // or noContent().build()
}

public void deleteCustomer(UUID customerId, String reason) {
  Customer customer = customerRepository.findById(customerId)
    .orElseThrow(() -> new CustomerNotFoundException("Customer " + customerId + " not found"));

  customer.setStatus(Status.INACTIVE);
  customer.setDeletedAt(LocalDateTime.now());
  customer.setDeletionReason(reason);
  customerRepository.save(customer);

  auditService.createAuditEntry(Operation.DELETE, "CUSTOMER", customerId, reason, user);
}
